const itemsContact=document.querySelectorAll(".carousel__schedules__slider__item"),fadeDurationContact=1e3;let currentIndexContact=0;function fadeOutContact(t){t.style.transition=`opacity ${fadeDurationContact}ms`,t.style.opacity=0,setTimeout(()=>{t.style.display="none",showNextContact()},fadeDurationContact)}function showNextContact(){currentIndexContact=(currentIndexContact+1)%itemsContact.length;const t=itemsContact[currentIndexContact];t.style.transition="none",t.style.display="flex",setTimeout(()=>{fadeInContact(t)},200)}function fadeInContact(t){t.style.transition=`opacity ${fadeDurationContact}ms`,t.style.opacity=1,setTimeout(()=>{fadeOutContact(t)},3e3)}for(let t=1;t<itemsContact.length;t++)itemsContact[t].style.display="none";fadeInContact(itemsContact[currentIndexContact]);